import { Calendar } from '@refy-design/web';
import { useState } from 'react';
export function Example() {
  const args = {};
  const [date, setDate] = useState<Date | null>(new Date());
  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 12,
        alignItems: 'flex-start',
      }}
    >
      <Calendar
        {...args}
        mode="single"
        value={date}
        onChange={(v) => setDate(v as Date)}
      />
      <code
        style={{ fontFamily: 'var(--font-mono)', fontSize: 12, color: 'var(--ink-2)' }}
      >
        {date ? date.toISOString().slice(0, 10) : 'no date'}
      </code>
    </div>
  );
}

import { Calendar } from '@refy-design/web';
import type { DateRange } from '@refy-design/web';
import { useState } from 'react';
export function Example() {
  const args = {};
  const [range, setRange] = useState<DateRange>({ start: null, end: null });
  const fmt = (d: Date | null) => (d ? d.toISOString().slice(0, 10) : '—');
  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 12,
        alignItems: 'flex-start',
      }}
    >
      <Calendar
        {...args}
        mode="range"
        numberOfMonths={2}
        value={range}
        onChange={(v) => setRange(v as DateRange)}
      />
      <code
        style={{ fontFamily: 'var(--font-mono)', fontSize: 12, color: 'var(--ink-2)' }}
      >
        {fmt(range.start)} → {fmt(range.end)}
      </code>
    </div>
  );
}

